const $=id=>document.getElementById(id),colors=['#238367','#92bda1','#b2c77c','#dfb770','#88a9bc','#b79dc4'];
const labels={'International Journal Articles':'วารสารนานาชาติ','International Proceedings':'ประชุมวิชาการนานาชาติ','National Journal Articles':'วารสารระดับชาติ','National Proceedings':'ประชุมวิชาการระดับชาติ'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.normalize('NFKC').replace(/\s+/g,' ').trim().toLowerCase();
let data,records,staff,selected,page=1,sort=-1,visible=[];
const yearlabel=y=>`${y+543} (${y})`, pname=p=>p==='DE'?'DE / AISE':p;
function option(id,value,label=value){const o=document.createElement('option');o.value=value;o.textContent=label;$(id).append(o)}
function dedup(rows){if($('count').value==='records')return rows.map(r=>({...r,authors:[r.name],programmes:r.programmes}));const map=new Map;for(const r of rows){const key=norm(r.detail);if(!map.has(key))map.set(key,{...r,authors:[],programmes:[]});const p=map.get(key);p.authors=[...new Set([...p.authors,r.name])];p.programmes=[...new Set([...p.programmes,...r.programmes])]}return [...map.values()]}
function filtered(){const start=+$('start').value,end=+$('end').value;return records.filter(r=>r.year>=start&&r.year<=end&&selected.has(r.name)&&(!$('programme').value||r.programmes.includes($('programme').value))&&(!$('type').value||r.type===$('type').value)&&(!$('index').value||r.index===$('index').value)&&(!$('psu').checked||r.psu==='Y'))}
function staffList(){const q=norm($('staffsearch').value);$('stafflist').replaceChildren();for(const name of staff.filter(n=>norm(n).includes(q))){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=selected.has(name);input.onchange=()=>{input.checked?selected.add(name):selected.delete(name);render()};label.append(input,document.createTextNode(name));$('stafflist').append(label)}}
function render(){page=1;const bad=+$('start').value>+$('end').value;$('validation').textContent=bad?'กรุณาเลือกปีเริ่มต้นไม่เกินปีสิ้นสุด':'';$('selected').textContent=selected.size===staff.length?'ทุกคน':`${selected.size} คน`;$('period').textContent=`พ.ศ. ${+$('start').value+543} – ${+$('end').value+543}`;const raw=filtered(),pubs=dedup(raw);const authors=new Set(raw.map(r=>r.name));const indexed=dedup(raw.filter(r=>/scopus/i.test(r.index))).length;const types=[...new Set(raw.map(r=>r.type))];$('stats').innerHTML=[['ผลงานทางวิชาการ',pubs.length,$('count').value==='unique'?'ผลงานไม่ซ้ำตามข้อความรายละเอียด':'รายการที่บันทึกแยกตามอาจารย์'],['อาจารย์ที่มีผลงาน',authors.size,`จากรายชื่อที่เลือก ${selected.size} คน`],['ผลงานในฐาน Scopus',indexed,`${pubs.length?Math.round(indexed/pubs.length*100):0}% ของผลงานที่แสดง`],['ประเภทผลงาน',types.length,'วารสารและการประชุมวิชาการ']].map(([t,v,n])=>`<div class="stat"><label>${t}</label><strong>${v.toLocaleString()}</strong><small>${n}</small></div>`).join('');drawChart(raw);drawTypes(pubs);ranking(raw);programmes(raw);const q=norm($('search').value);visible=pubs.filter(r=>norm(r.detail+' '+r.authors.join(' ')).includes(q)).sort((a,b)=>sort*(a.year-b.year)||a.detail.localeCompare(b.detail));table()}
function drawChart(raw){const group=$('group').value,years=[];for(let y=+$('start').value;y<=+$('end').value;y++)years.push(y);let groups=group==='total'?['ผลงานรวม']:group==='type'?[...new Set(raw.map(r=>r.type))]:[...new Set(raw.flatMap(r=>r.programmes))];const series=groups.map(g=>years.map(y=>dedup(raw.filter(r=>r.year===y&&(group==='total'||(group==='type'?r.type===g:r.programmes.includes(g))))).length));$('legend').innerHTML=groups.map((g,i)=>`<span><i style="background:${colors[i%6]}"></i>${esc(labels[g]||pname(g))}</span>`).join('');if(!raw.length){$('chart').innerHTML='<div class="empty">ไม่พบผลงานในเงื่อนไขที่เลือก</div>';return}const W=700,H=260,L=36,R=12,T=15,B=32,max=Math.max(1,...years.map((_,i)=>series.reduce((s,a)=>s+a[i],0))),top=Math.ceil(max/5)*5,plotH=H-T-B,step=(W-L-R)/years.length,bw=Math.min(40,step*.55);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="กราฟจำนวนผลงานรายปี">`;for(let i=0;i<=4;i++){let y=T+plotH*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#edf1ed"/><text x="${L-8}" y="${y+4}" text-anchor="end">${Math.round(top*(1-i/4))}</text>`}years.forEach((yr,i)=>{let bottom=H-B;series.forEach((a,k)=>{const h=a[i]/top*plotH;bottom-=h;svg+=`<rect x="${L+i*step+(step-bw)/2}" y="${bottom}" width="${bw}" height="${h}" rx="2" fill="${colors[k%6]}"><title>${yr+543} (${yr}) · ${esc(labels[groups[k]]||pname(groups[k]))}: ${a[i]}</title></rect>`});if(years.length<13||i%Math.ceil(years.length/10)===0)svg+=`<text x="${L+(i+.5)*step}" y="${H-10}" text-anchor="middle">${yr+543}</text>`});$('chart').innerHTML=svg+'</svg>'}
function drawTypes(pubs){const types=Object.keys(labels),counts=types.map(t=>pubs.filter(r=>r.type===t).length);let a=0;const segments=counts.map((v,i)=>{const start=a;a+=pubs.length?v/pubs.length*100:0;return `${colors[i]} ${start}% ${a}%`});$('donut').innerHTML=`<div class="ring" style="background:${pubs.length?'conic-gradient('+segments.join(',')+')':'#edf1ed'}"><div class="ringcenter"><b>${pubs.length}</b><small>ผลงานทั้งหมด</small></div></div>`;$('types').innerHTML=types.map((t,i)=>`<div class="typeitem"><span><i style="background:${colors[i]}"></i>${labels[t]}</span><b>${counts[i]} <span style="color:#95a397;font-weight:400">(${pubs.length?Math.round(counts[i]/pubs.length*100):0}%)</span></b></div>`).join('')}
function ranking(raw){const ranks=[...new Set(raw.map(r=>r.name))].map(n=>[n,dedup(raw.filter(r=>r.name===n)).length]).sort((a,b)=>b[1]-a[1]).slice(0,8);$('ranking').innerHTML=ranks.length?ranks.map(([n,v],i)=>`<div class="rank"><span class="ranknum">${String(i+1).padStart(2,'0')}</span><div class="ranklabel">${esc(n)}<div class="bar"><i style="width:${v/ranks[0][1]*100}%"></i></div></div><b>${v}</b></div>`).join(''):'<p>ไม่พบข้อมูล</p>'}
function programmes(raw){const values=[...new Set(raw.flatMap(r=>r.programmes))].map(p=>[p,dedup(raw.filter(r=>r.programmes.includes(p))).length]).sort((a,b)=>b[1]-a[1]);$('programmes').innerHTML=values.length?values.map(([p,n],i)=>`<div class="programrow"><div><span>${esc(pname(p))}</span><b>${n} <small>ผลงาน</small></b></div><div class="bar"><i style="width:${n/values[0][1]*100}%;background:${colors[i%6]}"></i></div></div>`).join(''):'<p>ไม่พบข้อมูล</p>'}
function table(){const pages=Math.max(1,Math.ceil(visible.length/10));page=Math.min(page,pages);$('resultcount').textContent=`(${visible.length.toLocaleString()})`;$('rows').innerHTML=visible.slice((page-1)*10,page*10).map((r,i)=>`<tr><td><b>${r.year+543}</b><small>${r.year}</small></td><td><div class="pubtitle" tabindex="0" role="button" data-row="${(page-1)*10+i}">${esc(r.detail)}</div></td><td>${r.authors.map(esc).join('<br>')}<small>${r.programmes.map(p=>esc(pname(p))).join(', ')}</small></td><td>${esc(labels[r.type]||r.type)}<small><span class="badge">${esc(r.index||'ไม่ระบุ')}</span></small></td></tr>`).join('')||'<tr><td colspan="4" class="empty">ไม่พบรายการที่ตรงกับตัวกรอง</td></tr>';$('pageinfo').textContent=`หน้า ${page} / ${pages} · ${visible.length} รายการ`;$('prev').disabled=page===1;$('next').disabled=page===pages;document.querySelectorAll('[data-row]').forEach(el=>{const open=()=>{const r=visible[+el.dataset.row];$('detailbody').innerHTML=`<h2>${esc(labels[r.type]||r.type)} · ${yearlabel(r.year)}</h2><p>${esc(r.detail)}</p><p><b>อาจารย์:</b> ${r.authors.map(esc).join(', ')}<br><b>หลักสูตร:</b> ${r.programmes.map(p=>esc(pname(p))).join(', ')}<br><b>ฐานดัชนี:</b> ${esc(r.index||'ไม่ระบุ')}<br><b>สังกัด PSU ตามรายการต้นฉบับ:</b> ${esc(r.psu||'ไม่ระบุ')}</p>`;$('detail').showModal()};el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter')open()}})}
function reset(){for(const id of ['programme','type','index'])$(id).value='';$('start').value='2020';$('end').value='2024';$('count').value='unique';$('group').value='total';$('psu').checked=false;$('search').value='';$('staffsearch').value='';selected=new Set(staff);staffList();render()}
fetch('data.json').then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(d=>{data=d;const map=new Map(d.staff.map(s=>[s.name,s.programmes]));records=d.publications.map((r,i)=>({...r,id:i,year:+r.year,index:r.index.trim(),programmes:map.get(r.name)||['ยังไม่ระบุหลักสูตร']}));staff=[...new Set([...d.staff.map(r=>r.name),...records.map(r=>r.name)])].sort();selected=new Set(staff);const years=[...new Set(records.map(r=>r.year))].sort((a,b)=>a-b);for(let y=years[0];y<=years.at(-1);y++){option('start',y,yearlabel(y));option('end',y,yearlabel(y))}for(const p of [...new Set(records.flatMap(r=>r.programmes))].sort())option('programme',p,pname(p));for(const t of Object.keys(labels))option('type',t,labels[t]);for(const i of [...new Set(records.map(r=>r.index))].sort())option('index',i,i||'ไม่ระบุ');const unmatched=[...new Set(records.filter(r=>!map.has(r.name)).map(r=>r.name))];$('quality').textContent=`ข้อมูลต้นฉบับ ${records.length} รายการ · อาจารย์ในไฟล์หลักสูตร ${d.staff.length} คน · ชื่อในไฟล์ผลงานที่ยังจับคู่หลักสูตรไม่ได้ ${unmatched.length} ชื่อ: ${unmatched.join(', ')} โดยคงชื่อเดิมไว้และไม่จับคู่ชื่อที่ไม่ครบโดยอัตโนมัติ`;reset()}).catch(()=>{$('stats').innerHTML='<p role="alert">ไม่สามารถโหลดข้อมูลได้ กรุณาเปิดเว็บผ่านเซิร์ฟเวอร์แล้วลองใหม่</p>'});
for(const id of ['start','end','programme','type','index','count','psu','group'])$(id).addEventListener('change',render);$('search').oninput=()=>render();$('staffsearch').oninput=staffList;$('allstaff').onclick=()=>{selected=new Set(staff);staffList();render()};$('nostaff').onclick=()=>{selected.clear();staffList();render()};$('reset').onclick=reset;$('prev').onclick=()=>{page--;table()};$('next').onclick=()=>{page++;table()};$('sortyear').onclick=()=>{sort*=-1;render()};$('close').onclick=()=>$('detail').close();$('export').onclick=()=>{const csv=[['ปี ค.ศ.','ปี พ.ศ.','อาจารย์','หลักสูตร','ประเภท','รายละเอียด','ฐานดัชนี'],...visible.map(r=>[r.year,r.year+543,r.authors.join('; '),r.programmes.join('; '),r.type,r.detail,r.index])].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));a.download=`coc-publications-${$('start').value}-${$('end').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
